import type { Ticker } from 'pixi.js';

export type Ease = (t: number) => number;

export const linear: Ease = (t) => t;
export const easeInOut: Ease = (t) => (t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2);

/** Runs `update` every frame with eased progress 0..1 for `ms`, resolves when done. */
export function tween(ticker: Ticker, ms: number, update: (t: number) => void, ease: Ease = easeInOut): Promise<void> {
  return new Promise((resolve) => {
    let elapsed = 0;
    const tick = (tk: Ticker) => {
      elapsed += tk.deltaMS;
      const t = Math.min(1, elapsed / ms);
      update(ease(t));
      if (t >= 1) {
        ticker.remove(tick);
        resolve();
      }
    };
    ticker.add(tick);
  });
}

export function wait(ticker: Ticker, ms: number): Promise<void> {
  return tween(ticker, ms, () => {}, linear);
}
