import { Container, Graphics, Text } from 'pixi.js';

export class Button extends Container {
  private readonly bg = new Graphics();
  private readonly caption: Text;
  private enabled = true;

  constructor(text: string, private w: number, private readonly h: number, private readonly color: number) {
    super();
    this.caption = new Text({
      text,
      style: { fontFamily: 'Arial, sans-serif', fontSize: h * 0.36, fontWeight: 'bold', fill: 0xffffff },
    });
    this.caption.anchor.set(0.5);
    this.caption.position.set(w / 2, h / 2);
    this.addChild(this.bg, this.caption);

    this.eventMode = 'static';
    this.cursor = 'pointer';
    this.on('pointerdown', () => this.enabled && this.draw(true));
    this.on('pointerup', () => this.draw(false));
    this.on('pointerupoutside', () => this.draw(false));
    this.draw(false);
  }

  setText(text: string): void {
    this.caption.text = text;
  }

  setWidth(w: number): void {
    if (w === this.w) return;
    this.w = w;
    this.caption.x = w / 2;
    this.draw(false);
  }

  setEnabled(enabled: boolean): void {
    this.enabled = enabled;
    this.eventMode = enabled ? 'static' : 'none';
    this.alpha = enabled ? 1 : 0.35;
  }

  isEnabled(): boolean {
    return this.enabled;
  }

  private draw(pressed: boolean): void {
    const offset = pressed ? 4 : 0;
    this.bg
      .clear()
      .roundRect(0, 6, this.w, this.h, 16)
      .fill({ color: 0x000000, alpha: 0.35 })
      .roundRect(0, offset, this.w, this.h, 16)
      .fill(this.color)
      .stroke({ width: 3, color: 0xffffff, alpha: 0.25 });
    this.caption.y = this.h / 2 + offset;
  }
}
