/**
 * Single source of randomness for game logic, swappable for a seeded generator
 * in simulations. Visual-only randomness (dice faces while spinning) may use Math.random.
 */
let generator: () => number = Math.random;

export function random(): number {
  return generator();
}

export function setRandom(fn: () => number): void {
  generator = fn;
}

export function randInt(min: number, max: number): number {
  return min + Math.floor(generator() * (max - min + 1));
}

/** Small, fast seeded PRNG (mulberry32). */
export function seeded(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
