import { CONFIG } from '../config';
import type { Camera } from '../view/Camera';
import type { ArrowPad } from '../view/ArrowPad';

const KEY_DIRS: Record<string, [number, number]> = {
  ArrowUp: [0, -1],
  ArrowDown: [0, 1],
  ArrowLeft: [-1, 0],
  ArrowRight: [1, 0],
};

/** Wheel zoom, two-finger pinch zoom/pan, arrow pad and arrow keys. Everything is ignored while disabled. */
export class CameraControls {
  private enabled = true;
  private readonly touches = new Map<number, { x: number; y: number }>();
  private readonly keys = new Set<string>();

  constructor(canvas: HTMLCanvasElement, private readonly camera: Camera, private readonly pad: ArrowPad) {
    canvas.style.touchAction = 'none';
    canvas.addEventListener('wheel', (e) => this.onWheel(e), { passive: false });
    canvas.addEventListener('pointerdown', (e) => this.onPointerDown(e));
    window.addEventListener('pointermove', (e) => this.onPointerMove(e));
    window.addEventListener('pointerup', (e) => this.touches.delete(e.pointerId));
    window.addEventListener('pointercancel', (e) => this.touches.delete(e.pointerId));
    window.addEventListener('keydown', (e) => {
      if (!KEY_DIRS[e.code]) return;
      e.preventDefault();
      if (this.enabled) this.keys.add(e.code);
    });
    window.addEventListener('keyup', (e) => this.keys.delete(e.code));
    window.addEventListener('blur', () => this.keys.clear());
    pad.onCenter = () => camera.follow();
  }

  setEnabled(enabled: boolean): void {
    this.enabled = enabled;
    this.pad.setEnabled(enabled);
    if (!enabled) {
      this.touches.clear();
      this.keys.clear();
    }
  }

  update(dtSec: number): void {
    if (!this.enabled) return;
    let dx = this.pad.direction.x;
    let dy = this.pad.direction.y;
    for (const code of this.keys) {
      dx += KEY_DIRS[code][0];
      dy += KEY_DIRS[code][1];
    }
    if (dx === 0 && dy === 0) return;
    const len = Math.hypot(dx, dy);
    const step = CONFIG.camera.panSpeed * dtSec;
    // Arrow points where the view should go, so the content moves the opposite way.
    this.camera.panBy((-dx / len) * step, (-dy / len) * step);
  }

  private onWheel(e: WheelEvent): void {
    e.preventDefault();
    if (!this.enabled || !this.camera.containsScreenPoint(e.clientX, e.clientY)) return;
    const pixels = e.deltaMode === 1 ? e.deltaY * 16 : e.deltaY;
    this.camera.zoomAt(e.clientX, e.clientY, Math.exp(-pixels * CONFIG.camera.wheelSensitivity));
  }

  private onPointerDown(e: PointerEvent): void {
    if (!this.enabled || e.pointerType !== 'touch') return;
    if (!this.camera.containsScreenPoint(e.clientX, e.clientY)) return;
    if (this.pad.getBounds().rectangle.contains(e.clientX, e.clientY)) return;
    this.touches.set(e.pointerId, { x: e.clientX, y: e.clientY });
  }

  private onPointerMove(e: PointerEvent): void {
    const prev = this.touches.get(e.pointerId);
    if (!prev) return;
    if (!this.enabled || this.touches.size !== 2) {
      prev.x = e.clientX;
      prev.y = e.clientY;
      return;
    }

    const [a, b] = [...this.touches.values()];
    const before = pinchOf(a, b);
    prev.x = e.clientX;
    prev.y = e.clientY;
    const after = pinchOf(a, b);

    if (before.dist > 0) this.camera.zoomAt(before.x, before.y, after.dist / before.dist);
    this.camera.panBy(after.x - before.x, after.y - before.y);
  }
}

function pinchOf(a: { x: number; y: number }, b: { x: number; y: number }) {
  return { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2, dist: Math.hypot(b.x - a.x, b.y - a.y) };
}
