import { Container, Graphics } from 'pixi.js';

type Dir = { x: number; y: number };

const DIRS: Dir[] = [
  { x: 0, y: -1 },
  { x: 1, y: 0 },
  { x: 0, y: 1 },
  { x: -1, y: 0 },
];

/** On-screen d-pad: hold an arrow to pan, tap the center to recenter on the player. */
export class ArrowPad extends Container {
  /** Currently held direction; (0, 0) when nothing is pressed. */
  readonly direction: Dir = { x: 0, y: 0 };
  onCenter: () => void = () => {};

  private readonly arrows: Graphics[] = [];
  private readonly center = new Graphics();
  private enabled = true;

  constructor() {
    super();
    for (const dir of DIRS) {
      const g = new Graphics();
      g.eventMode = 'static';
      g.cursor = 'pointer';
      g.on('pointerdown', () => this.press(dir));
      g.on('pointerup', () => this.release());
      g.on('pointerupoutside', () => this.release());
      g.on('pointerleave', () => this.release());
      this.arrows.push(g);
      this.addChild(g);
    }
    this.center.eventMode = 'static';
    this.center.cursor = 'pointer';
    this.center.on('pointertap', () => this.enabled && this.onCenter());
    this.addChild(this.center);
  }

  /** Lays the pad out with its top-left at (0, 0); total size is 3 * buttonSize. */
  draw(buttonSize: number): void {
    const r = buttonSize * 0.46;
    const c = buttonSize * 1.5;
    DIRS.forEach((dir, i) => {
      const cx = c + dir.x * buttonSize;
      const cy = c + dir.y * buttonSize;
      const t = r * 0.5;
      // Triangle pointing along `dir`.
      const px = -dir.y;
      const py = dir.x;
      this.arrows[i]
        .clear()
        .circle(cx, cy, r)
        .fill({ color: 0x0e131d, alpha: 0.75 })
        .stroke({ width: 2, color: 0x8da0c0, alpha: 0.6 })
        .poly([
          cx + dir.x * t, cy + dir.y * t,
          cx - dir.x * t * 0.6 + px * t, cy - dir.y * t * 0.6 + py * t,
          cx - dir.x * t * 0.6 - px * t, cy - dir.y * t * 0.6 - py * t,
        ])
        .fill(0xffffff);
    });
    this.center
      .clear()
      .circle(c, c, r * 0.85)
      .fill({ color: 0x0e131d, alpha: 0.75 })
      .stroke({ width: 2, color: 0xffd166, alpha: 0.8 })
      .circle(c, c, r * 0.45)
      .stroke({ width: 3, color: 0xffd166 })
      .circle(c, c, r * 0.14)
      .fill(0xffd166);
  }

  setEnabled(enabled: boolean): void {
    if (enabled === this.enabled) return;
    this.enabled = enabled;
    this.alpha = enabled ? 1 : 0.3;
    this.interactiveChildren = enabled;
    this.release();
  }

  private press(dir: Dir): void {
    if (!this.enabled) return;
    this.direction.x = dir.x;
    this.direction.y = dir.y;
  }

  private release(): void {
    this.direction.x = 0;
    this.direction.y = 0;
  }
}
