import { CONFIG, FINISH_INDEX } from '../config';
import { random, randInt } from '../rng';
import { CELL_MULTIPLIERS } from './multipliers';

export type LinkKind = 'ladder' | 'rope';

export interface Link {
  from: number;
  to: number;
  kind: LinkKind;
}

/** Links keyed by their source cell. */
export type LinkMap = Map<number, Link>;

export interface BoardSetup {
  links: LinkMap;
  /** Unopened lootbox cells; opened boxes are removed during the round. */
  lootboxes: Set<number>;
}

export type LootItem = 'money' | 'jump' | 'bonusDice';

export function multiplierAt(cell: number): number {
  return CELL_MULTIPLIERS[cell];
}

export function round2(v: number): number {
  return Math.round(v * 100) / 100;
}

/** Every cell a link starts or ends on. */
export function linkCells(links: LinkMap): Set<number> {
  const cells = new Set<number>();
  for (const l of links.values()) {
    cells.add(l.from);
    cells.add(l.to);
  }
  return cells;
}

/** Cells a fatal can never be placed on: link ends and lootboxes. */
export function blockedCells(setup: BoardSetup): Set<number> {
  const cells = linkCells(setup.links);
  for (const c of setup.lootboxes) cells.add(c);
  return cells;
}

/**
 * Generates ladders, ropes and lootboxes for a round. The fixed rope on the last
 * cell is always present; the rest is random, with no two items sharing a cell,
 * and every 6-cell window keeping at least one cell free for a fatal.
 */
export function generateBoard(): BoardSetup {
  for (let attempt = 0; attempt < 500; attempt++) {
    const links = tryPlaceLinks();
    if (!links) continue;
    const lootboxes = tryPlaceLootboxes(linkCells(links));
    if (!lootboxes) continue;
    const setup = { links, lootboxes };
    if (everyWindowHasFreeCell(blockedCells(setup))) return setup;
  }
  throw new Error('Could not generate board; relax CONFIG.links / CONFIG.loot');
}

function tryPlaceLinks(): LinkMap | null {
  const { cellCount } = CONFIG.board;
  const { ladders, ropes, minLength, maxLength, fixedRope } = CONFIG.links;
  const links: LinkMap = new Map();
  links.set(fixedRope.from, { from: fixedRope.from, to: fixedRope.to, kind: 'rope' });
  const used = linkCells(links);

  const place = (kind: LinkKind) => {
    for (let tries = 0; tries < 200; tries++) {
      const len = randInt(minLength, maxLength);
      // Keep links off the last two cells so the end game stays as designed.
      const from = kind === 'ladder' ? randInt(1, cellCount - 2 - len) : randInt(1 + len, cellCount - 2);
      const to = kind === 'ladder' ? from + len : from - len;
      if (from < 1 || to < 1 || to > cellCount - 2) continue;
      if (used.has(from) || used.has(to)) continue;
      links.set(from, { from, to, kind });
      used.add(from);
      used.add(to);
      return true;
    }
    return false;
  };

  for (let i = 0; i < ladders; i++) if (!place('ladder')) return null;
  for (let i = 0; i < ropes; i++) if (!place('rope')) return null;
  return links;
}

/**
 * One lootbox per equal section of the board (two halves by default), never on a
 * link cell and never on the last `excludeLast` cells.
 */
function tryPlaceLootboxes(used: Set<number>): Set<number> | null {
  const last = CONFIG.board.cellCount;
  const { count, excludeLast } = CONFIG.loot;
  const boxes = new Set<number>();
  for (let i = 0; i < count; i++) {
    const from = Math.floor((i * last) / count) + 1;
    const to = Math.min(Math.floor(((i + 1) * last) / count), last - excludeLast);
    const free: number[] = [];
    for (let c = from; c <= to; c++) if (!used.has(c)) free.push(c);
    if (free.length === 0) return null;
    boxes.add(free[randInt(0, free.length - 1)]);
  }
  return boxes;
}

function everyWindowHasFreeCell(blocked: Set<number>): boolean {
  // From the cell right before the final rope, that rope is the only cell ahead and the only risk.
  const lastChecked = CONFIG.links.fixedRope.from - 2;
  for (let pos = 0; pos <= lastChecked; pos++) {
    if (fatalCandidates(pos, blocked).length === 0) return false;
  }
  return true;
}

function fatalCandidates(pos: number, blocked: Set<number>): number[] {
  const { cellCount } = CONFIG.board;
  const out: number[] = [];
  for (let c = pos + 1; c <= Math.min(pos + CONFIG.fatal.window, cellCount); c++) {
    if (!blocked.has(c)) out.push(c);
  }
  return out;
}

function fatalZone(pos: number): { min: number; max: number } {
  let zone: { min: number; max: number } = CONFIG.fatal.zones[0];
  for (const z of CONFIG.fatal.zones) if (z.fromCell <= pos) zone = z;
  return zone;
}

/** Picks the fatal cells ahead of `pos`. Empty only when nothing but the final rope and Finish is ahead. */
export function generateFatal(pos: number, setup: BoardSetup): Set<number> {
  const candidates = fatalCandidates(pos, blockedCells(setup));
  const zone = fatalZone(pos);
  const count = Math.min(candidates.length, randInt(zone.min, zone.max));
  const fatal = new Set<number>();
  while (fatal.size < count) {
    fatal.add(candidates[Math.floor(random() * candidates.length)]);
  }
  return fatal;
}

export function rollLoot(): LootItem {
  const entries = Object.entries(CONFIG.loot.weights) as [LootItem, number][];
  let r = random() * entries.reduce((s, [, w]) => s + w, 0);
  for (const [item, w] of entries) {
    if ((r -= w) < 0) return item;
  }
  return entries[entries.length - 1][0];
}

/**
 * Picks a jump target 3-6 cells ahead that lands on a plain cell (no link start,
 * no lootbox). Anything past the last cell counts as Finish. Null if nothing fits.
 * The target can never be fatal: fatal cells are regenerated ahead of it afterwards.
 */
export function pickJumpTarget(pos: number, setup: BoardSetup): number | null {
  const { min, max } = CONFIG.loot.jumpSteps;
  const options: number[] = [];
  for (let n = min; n <= max; n++) {
    const t = Math.min(pos + n, FINISH_INDEX);
    if (t === FINISH_INDEX || (!setup.links.has(t) && !setup.lootboxes.has(t))) options.push(t);
  }
  return options.length ? options[randInt(0, options.length - 1)] : null;
}
