import { Container, Graphics, Text } from 'pixi.js';
import { Button } from './Button';
import { Dice } from './Dice';
import type { Rect } from './Camera';

class Stat extends Container {
  private readonly value: Text;

  constructor(label: string) {
    super();
    const title = new Text({
      text: label,
      style: { fontFamily: 'Arial, sans-serif', fontSize: 16, fontWeight: 'bold', fill: 0x8da0c0, letterSpacing: 1 },
    });
    this.value = new Text({
      text: '',
      style: { fontFamily: 'Arial, sans-serif', fontSize: 32, fontWeight: 'bold', fill: 0xffffff },
    });
    this.value.y = 22;
    this.addChild(title, this.value);
  }

  set(text: string, color = 0xffffff): void {
    this.value.text = text;
    this.value.style.fill = color;
  }
}

export interface HudStats {
  balance: string;
  bet: string;
  multiplier: string;
  win: string;
}

/** Positions of the HUD elements in a fixed design space, which is then scaled to fit the panel. */
interface Design {
  w: number;
  h: number;
  stats: [number, number][];
  dice: [number, number];
  /** Dice positions and scale when the bonus dice is shown next to the main one. */
  twoDice: { a: [number, number]; b: [number, number]; scale: number };
  roll: [number, number];
  cash: [number, number];
  buttonW: number;
}

const VERTICAL: Design = {
  w: 300,
  h: 520,
  stats: [[20, 20], [170, 20], [20, 100], [170, 100]],
  dice: [150, 260],
  twoDice: { a: [80, 260], b: [220, 260], scale: 0.95 },
  roll: [20, 350],
  cash: [20, 440],
  buttonW: 260,
};

const HORIZONTAL: Design = {
  w: 650,
  h: 230,
  stats: [[20, 25], [150, 25], [20, 125], [150, 125]],
  dice: [345, 115],
  twoDice: { a: [345, 65], b: [345, 165], scale: 0.62 },
  roll: [430, 25],
  cash: [430, 125],
  buttonW: 200,
};

const BUTTON_H = 75;

export class Hud extends Container {
  readonly dice = new Dice(130);
  /** Gold dice shown while the lootbox bonus dice is active. */
  readonly bonusDice = new Dice(130, 0xffd166);
  readonly rollButton = new Button('ROLL', VERTICAL.buttonW, BUTTON_H, 0x2f8f4e);
  readonly cashButton = new Button('CASH OUT', VERTICAL.buttonW, BUTTON_H, 0xc98a14);

  private design: Design = VERTICAL;
  private readonly panel = new Graphics();
  private readonly content = new Container();
  private readonly stats = {
    balance: new Stat('BALANCE'),
    bet: new Stat('BET'),
    multiplier: new Stat('MULTIPLIER'),
    win: new Stat('WIN'),
  };

  constructor() {
    super();
    const s = this.stats;
    this.content.addChild(s.balance, s.bet, s.multiplier, s.win, this.dice, this.bonusDice, this.rollButton, this.cashButton);
    this.bonusDice.visible = false;
    this.addChild(this.panel, this.content);
  }

  setStats(stats: HudStats, winColor = 0xffffff): void {
    this.stats.balance.set(stats.balance);
    this.stats.bet.set(stats.bet);
    this.stats.multiplier.set(stats.multiplier, 0xffd166);
    this.stats.win.set(stats.win, winColor);
  }

  setBonusDice(active: boolean): void {
    this.bonusDice.visible = active;
    this.layoutDice();
  }

  private layoutDice(): void {
    const d = this.design;
    if (this.bonusDice.visible) {
      this.dice.position.set(...d.twoDice.a);
      this.bonusDice.position.set(...d.twoDice.b);
      this.dice.scale.set(d.twoDice.scale);
      this.bonusDice.scale.set(d.twoDice.scale);
    } else {
      this.dice.position.set(...d.dice);
      this.dice.scale.set(1);
    }
  }

  layout(panel: Rect, portrait: boolean): void {
    this.panel
      .clear()
      .rect(panel.x, panel.y, panel.w, panel.h)
      .fill(0x0e131d)
      .rect(panel.x, panel.y, portrait ? panel.w : 3, portrait ? 3 : panel.h)
      .fill(0x2c3a55);

    // Mobile layouts use the horizontal arrangement in a bottom panel.
    const d = portrait ? HORIZONTAL : VERTICAL;
    const s = this.stats;
    [s.balance, s.bet, s.multiplier, s.win].forEach((stat, i) => stat.position.set(...d.stats[i]));
    this.design = d;
    this.layoutDice();
    this.rollButton.position.set(...d.roll);
    this.cashButton.position.set(...d.cash);
    this.rollButton.setWidth(d.buttonW);
    this.cashButton.setWidth(d.buttonW);

    const scale = Math.min(panel.w / d.w, panel.h / d.h, 1.4);
    this.content.scale.set(scale);
    this.content.position.set(panel.x + (panel.w - d.w * scale) / 2, panel.y + (panel.h - d.h * scale) / 2);
  }
}
