import { Container, Graphics, Text } from 'pixi.js';

/** Big centered message shown over the play area (bust, cash out, finish). */
export class Banner extends Container {
  private readonly bg = new Graphics();
  private readonly title: Text;
  private readonly subtitle: Text;

  constructor() {
    super();
    this.title = new Text({
      text: '',
      style: { fontFamily: 'Arial, sans-serif', fontSize: 56, fontWeight: 'bold', fill: 0xffffff, stroke: { color: 0x000000, width: 6 } },
    });
    this.subtitle = new Text({
      text: '',
      style: { fontFamily: 'Arial, sans-serif', fontSize: 26, fontWeight: 'bold', fill: 0xffffff },
    });
    this.title.anchor.set(0.5);
    this.subtitle.anchor.set(0.5);
    this.title.y = -18;
    this.subtitle.y = 36;
    this.addChild(this.bg, this.title, this.subtitle);
    this.visible = false;
  }

  show(title: string, subtitle: string, color: number): void {
    this.title.text = title;
    this.title.style.fill = color;
    this.subtitle.text = subtitle;
    const w = Math.max(this.title.width, this.subtitle.width) + 80;
    this.bg.clear().roundRect(-w / 2, -70, w, 140, 24).fill({ color: 0x0e131d, alpha: 0.88 }).stroke({ width: 4, color, alpha: 0.8 });
    this.visible = true;
  }

  hide(): void {
    this.visible = false;
  }
}
