import type { Container } from 'pixi.js';
import { CONFIG } from '../config';

export interface Rect {
  x: number;
  y: number;
  w: number;
  h: number;
}

/**
 * Centers `target` (a child of `world`) inside the viewport rect while following.
 * Manual pan/zoom switches to free mode until `follow()` is called again.
 */
export class Camera {
  private viewport: Rect = { x: 0, y: 0, w: 1, h: 1 };
  private focusX = 0;
  private focusY = 0;
  private following = true;
  private zoom = 1;

  constructor(private readonly world: Container, private readonly target: Container) {}

  setViewport(rect: Rect): void {
    this.viewport = rect;
    this.clampFocus();
    this.apply();
  }

  containsScreenPoint(sx: number, sy: number): boolean {
    const { x, y, w, h } = this.viewport;
    return sx >= x && sx <= x + w && sy >= y && sy <= y + h;
  }

  /** Smoothly returns to the target and keeps following it. */
  follow(): void {
    this.following = true;
  }

  snap(): void {
    this.focusX = this.target.x;
    this.focusY = this.target.y;
    this.clampFocus();
    this.apply();
  }

  /** Moves the view by a screen-space delta (content moves with the finger/drag direction). */
  panBy(dx: number, dy: number): void {
    this.following = false;
    const s = this.scale();
    this.focusX -= dx / s;
    this.focusY -= dy / s;
    this.clampFocus();
    this.apply();
  }

  /** Multiplies zoom by `factor`, keeping the world point under (sx, sy) in place. */
  zoomAt(sx: number, sy: number, factor: number): void {
    const { minZoom, maxZoom } = CONFIG.camera;
    const next = Math.max(minZoom, Math.min(maxZoom, this.zoom * factor));
    if (next === this.zoom) return;

    this.following = false;
    this.clampFocus();
    const { x, y, w, h } = this.viewport;
    const ox = sx - x - w / 2;
    const oy = sy - y - h / 2;
    const worldX = this.focusX + ox / this.scale();
    const worldY = this.focusY + oy / this.scale();
    this.zoom = next;
    this.focusX = worldX - ox / this.scale();
    this.focusY = worldY - oy / this.scale();
    this.clampFocus();
    this.apply();
  }

  update(dtSec: number): void {
    if (!this.following) return;
    const k = 1 - Math.exp(-CONFIG.camera.followSpeed * dtSec);
    this.focusX += (this.target.x - this.focusX) * k;
    this.focusY += (this.target.y - this.focusY) * k;
    this.apply();
  }

  private scale(): number {
    const { w, h } = this.viewport;
    return (Math.min(w, h) / CONFIG.camera.viewWorldSize) * this.zoom;
  }

  /** Keeps the board filling the view where possible instead of showing empty space past its edges. */
  private clampFocus(): void {
    const { w, h } = this.viewport;
    const s = this.scale();
    this.focusX = clampAxis(this.focusX, w / 2 / s, CONFIG.world.size);
    this.focusY = clampAxis(this.focusY, h / 2 / s, CONFIG.world.size);
  }

  private apply(): void {
    const { x, y, w, h } = this.viewport;
    const s = this.scale();
    // While following, the raw focus tracks the token; clamp only what is displayed.
    const fx = clampAxis(this.focusX, w / 2 / s, CONFIG.world.size);
    const fy = clampAxis(this.focusY, h / 2 / s, CONFIG.world.size);
    this.world.scale.set(s);
    this.world.position.set(x + w / 2 - fx * s, y + h / 2 - fy * s);
  }
}

function clampAxis(focus: number, halfView: number, size: number): number {
  if (halfView * 2 >= size) return size / 2;
  return Math.max(halfView, Math.min(size - halfView, focus));
}
