import { Container, Graphics } from 'pixi.js';

export class Token extends Container {
  private readonly body = new Graphics();

  constructor() {
    super();
    const shadow = new Graphics().ellipse(0, 34, 38, 12).fill({ color: 0x000000, alpha: 0.35 });
    this.addChild(shadow, this.body);
    this.setColor(0xffd166);
  }

  setColor(color: number): void {
    this.body
      .clear()
      .circle(0, 0, 42)
      .fill(color)
      .stroke({ width: 7, color: 0xffffff })
      .circle(-12, -12, 10)
      .fill({ color: 0xffffff, alpha: 0.6 });
  }
}
