import { Container, Graphics, Text } from 'pixi.js';
import { CONFIG, FINISH_INDEX, START_INDEX } from '../config';
import type { Point } from '../board/layout';
import { multiplierAt, type Link, type LinkMap } from '../board/rules';
import { FINISH_MULTIPLIER } from '../board/multipliers';

const COLORS = {
  background: 0x1b2333,
  grid: 0x222c3f,
  arrow: 0x56688a,
  cell: 0x2c3a55,
  cellStroke: 0x4b5e82,
  hotCell: 0x553660,
  start: 0x2f6fb0,
  finish: 0xd4a017,
  ladder: 0x46c46a,
  ladderCell: 0x24452f,
  rope: 0xe0674f,
  ropeCell: 0x4a2a2a,
  fatal: 0xb3202a,
  fatalMark: 0x3a0508,
};

export class BoardView extends Container {
  private readonly pathLayer = new Container();
  private readonly cellLayer = new Container();
  private readonly fatalLayer = new Container();
  private readonly linkLayer = new Container();
  private readonly labelLayer = new Container();
  private readonly lootLayer = new Container();

  private readonly cells: Graphics[] = [];
  private readonly fatalMarks = new Map<number, Graphics>();
  private elapsed = 0;

  constructor(private readonly points: Point[]) {
    super();
    this.addChild(this.createBackground(), this.pathLayer, this.cellLayer, this.fatalLayer, this.linkLayer, this.labelLayer, this.lootLayer);
    this.drawPath();
    this.createCells();
  }

  cellPosition(index: number): Point {
    return this.points[index];
  }

  setLinks(links: LinkMap): void {
    for (let i = 1; i <= CONFIG.board.cellCount; i++) this.drawCell(i, links.get(i));

    this.linkLayer.removeChildren().forEach((c) => c.destroy());
    for (const link of links.values()) {
      const g = new Graphics();
      if (link.kind === 'ladder') this.drawLadder(g, this.points[link.from], this.points[link.to]);
      else this.drawRope(g, this.points[link.from], this.points[link.to]);
      g.alpha = 0.9;
      this.linkLayer.addChild(g);
    }
  }

  setLootboxes(cells: Set<number>): void {
    this.lootLayer.removeChildren().forEach((c) => c.destroy());
    for (const cell of cells) {
      const p = this.points[cell];
      const box = createLootbox();
      box.label = `loot-${cell}`;
      box.position.set(p.x + CONFIG.board.cellRadius * 0.62, p.y - CONFIG.board.cellRadius * 0.62);
      this.lootLayer.addChild(box);
    }
  }

  lootbox(cell: number): Container | null {
    return this.lootLayer.getChildByLabel(`loot-${cell}`);
  }

  setFatal(fatal: Set<number>): void {
    for (const [cell, mark] of this.fatalMarks) mark.visible = fatal.has(cell);
  }

  update(dtMs: number): void {
    this.elapsed += dtMs;
    this.fatalLayer.alpha = 0.8 + 0.2 * Math.sin(this.elapsed / 180);
    for (const box of this.lootLayer.children) box.rotation = Math.sin(this.elapsed / 250) * 0.08;
  }

  private createBackground(): Graphics {
    const { size } = CONFIG.world;
    const g = new Graphics().roundRect(0, 0, size, size, 60).fill(COLORS.background);
    for (let v = 125; v < size; v += 125) {
      g.moveTo(v, 0).lineTo(v, size).moveTo(0, v).lineTo(size, v);
    }
    g.stroke({ width: 2, color: COLORS.grid });
    return g;
  }

  private radiusOf(index: number): number {
    return index === START_INDEX || index === FINISH_INDEX ? CONFIG.board.endRadius : CONFIG.board.cellRadius;
  }

  private drawPath(): void {
    const g = new Graphics();
    for (let i = 0; i < this.points.length - 1; i++) {
      const a = this.points[i];
      const b = this.points[i + 1];
      const dx = b.x - a.x;
      const dy = b.y - a.y;
      const len = Math.hypot(dx, dy);
      const ux = dx / len;
      const uy = dy / len;
      const sx = a.x + ux * (this.radiusOf(i) + 10);
      const sy = a.y + uy * (this.radiusOf(i) + 10);
      const ex = b.x - ux * (this.radiusOf(i + 1) + 10);
      const ey = b.y - uy * (this.radiusOf(i + 1) + 10);
      const head = 22;
      g.moveTo(sx, sy)
        .lineTo(ex - ux * head * 0.6, ey - uy * head * 0.6)
        .stroke({ width: 7, color: COLORS.arrow, cap: 'round' });
      g.poly([
        ex, ey,
        ex - ux * head - uy * head * 0.6, ey - uy * head + ux * head * 0.6,
        ex - ux * head + uy * head * 0.6, ey - uy * head - ux * head * 0.6,
      ]).fill(COLORS.arrow);
    }
    this.pathLayer.addChild(g);
  }

  private createCells(): void {
    for (let i = 0; i < this.points.length; i++) {
      const p = this.points[i];
      const g = new Graphics();
      g.position.set(p.x, p.y);
      this.cells.push(g);
      this.cellLayer.addChild(g);

      if (i === START_INDEX || i === FINISH_INDEX) {
        const isStart = i === START_INDEX;
        const r = CONFIG.board.endRadius;
        g.circle(0, 0, r).fill(isStart ? COLORS.start : COLORS.finish).stroke({ width: 8, color: 0xffffff, alpha: 0.8 });
        this.addLabel(isStart ? 'START' : 'FINISH', p.x, p.y - (isStart ? 0 : 16), 30, 0xffffff);
        if (!isStart) this.addLabel(`x${FINISH_MULTIPLIER}`, p.x, p.y + 24, 30, 0xffffff);
        continue;
      }

      this.drawCell(i, undefined);
      this.addLabel(String(i), p.x, p.y - 38, 20, 0x9fb0cc);
      this.addLabel(`x${multiplierAt(i).toFixed(2)}`, p.x, p.y + 4, 28, 0xffffff);

      const mark = new Graphics();
      const r = CONFIG.board.cellRadius;
      const s = r * 0.5;
      mark.circle(0, 0, r).fill(COLORS.fatal);
      mark.moveTo(-s, -s).lineTo(s, s).moveTo(s, -s).lineTo(-s, s).stroke({ width: 14, color: COLORS.fatalMark, cap: 'round' });
      mark.position.set(p.x, p.y);
      mark.visible = false;
      this.fatalMarks.set(i, mark);
      this.fatalLayer.addChild(mark);
    }
  }

  private drawCell(index: number, link: Link | undefined): void {
    const g = this.cells[index];
    const r = CONFIG.board.cellRadius;
    const heat = (index - 1) / (CONFIG.board.cellCount - 1);
    let fill = lerpColor(COLORS.cell, COLORS.hotCell, heat);
    let stroke: number = COLORS.cellStroke;
    let width = 5;
    if (link?.kind === 'ladder') {
      fill = COLORS.ladderCell;
      stroke = COLORS.ladder;
      width = 10;
    } else if (link?.kind === 'rope') {
      fill = COLORS.ropeCell;
      stroke = COLORS.rope;
      width = 10;
    }
    g.clear().circle(0, 0, r).fill(fill).stroke({ width, color: stroke });
  }

  private addLabel(text: string, x: number, y: number, fontSize: number, fill: number): void {
    const t = new Text({
      text,
      style: { fontFamily: 'Arial, sans-serif', fontSize, fontWeight: 'bold', fill, stroke: { color: 0x000000, width: 4 } },
    });
    t.anchor.set(0.5);
    t.position.set(x, y);
    this.labelLayer.addChild(t);
  }

  private drawLadder(g: Graphics, a: Point, b: Point): void {
    const { ux, uy, len } = dir(a, b);
    const px = -uy * 18;
    const py = ux * 18;
    for (let d = 20; d < len - 10; d += 38) {
      const x = a.x + ux * d;
      const y = a.y + uy * d;
      g.moveTo(x - px, y - py).lineTo(x + px, y + py);
    }
    g.stroke({ width: 6, color: COLORS.ladder });
    g.moveTo(a.x - px, a.y - py).lineTo(b.x - px, b.y - py);
    g.moveTo(a.x + px, a.y + py).lineTo(b.x + px, b.y + py);
    g.stroke({ width: 9, color: COLORS.ladder, cap: 'round' });
    endMarker(g, b, COLORS.ladder);
  }

  private drawRope(g: Graphics, a: Point, b: Point): void {
    const { ux, uy, len } = dir(a, b);
    const steps = Math.max(8, Math.floor(len / 12));
    const wave = (d: number) => Math.sin((d / 70) * Math.PI * 2) * 14;
    for (const [width, color] of [[14, 0x5a2a20], [8, COLORS.rope]] as const) {
      g.moveTo(a.x, a.y);
      for (let s = 1; s <= steps; s++) {
        const d = (s / steps) * len;
        const w = wave(d) * Math.sin((s / steps) * Math.PI);
        g.lineTo(a.x + ux * d - uy * w, a.y + uy * d + ux * w);
      }
      g.stroke({ width, color, cap: 'round', join: 'round' });
    }
    endMarker(g, b, COLORS.rope);
  }
}

/** Placeholder chest: brown box, gold lid band and lock, "?" on the front. */
function createLootbox(): Container {
  const c = new Container();
  const w = 64;
  const h = 50;
  const g = new Graphics()
    .roundRect(-w / 2 + 3, -h / 2 + 6, w, h, 8)
    .fill({ color: 0x000000, alpha: 0.4 })
    .roundRect(-w / 2, -h / 2, w, h, 8)
    .fill(0x8a5a2b)
    .stroke({ width: 4, color: 0x3d2410 })
    .rect(-w / 2, -h / 2 + 12, w, 8)
    .fill(0xf2c14e)
    .roundRect(-7, -h / 2 + 8, 14, 18, 3)
    .fill(0xf2c14e)
    .stroke({ width: 2, color: 0x3d2410 });
  const q = new Text({
    text: '?',
    style: { fontFamily: 'Arial, sans-serif', fontSize: 26, fontWeight: 'bold', fill: 0xffe08a, stroke: { color: 0x3d2410, width: 4 } },
  });
  q.anchor.set(0.5);
  q.y = 10;
  c.addChild(g, q);
  return c;
}

function dir(a: Point, b: Point) {
  const dx = b.x - a.x;
  const dy = b.y - a.y;
  const len = Math.hypot(dx, dy);
  return { ux: dx / len, uy: dy / len, len };
}

function endMarker(g: Graphics, p: Point, color: number): void {
  g.circle(p.x, p.y, CONFIG.board.cellRadius + 8).stroke({ width: 5, color, alpha: 0.8 });
}

function lerpColor(a: number, b: number, t: number): number {
  const ch = (c: number, s: number) => (c >> s) & 0xff;
  const mix = (s: number) => Math.round(ch(a, s) + (ch(b, s) - ch(a, s)) * t) << s;
  return mix(16) | mix(8) | mix(0);
}
