import { CONFIG, FINISH_INDEX } from '../config';

export interface Point {
  x: number;
  y: number;
}

type Segment =
  | { kind: 'line'; a: Point; b: Point; length: number }
  | { kind: 'arc'; cx: number; cy: number; r: number; a0: number; a1: number; length: number };

/**
 * Builds a snake path (up, down, up, ... joined by semicircles) and places
 * Start, all cells and Finish at equal distances along it.
 * Returns FINISH_INDEX + 1 points: [Start, cell 1..N, Finish].
 */
export function buildBoardPoints(): Point[] {
  const { size, margin } = CONFIG.world;
  const { columns } = CONFIG.board;

  const r = (size - 2 * margin) / (2 * (columns - 1));
  const top = margin + r;
  const bottom = size - margin - r;
  const colX = (i: number) => margin + i * 2 * r;

  const segments: Segment[] = [];
  const line = (a: Point, b: Point) =>
    segments.push({ kind: 'line', a, b, length: Math.hypot(b.x - a.x, b.y - a.y) });
  const arc = (cx: number, cy: number, a0: number, a1: number) =>
    segments.push({ kind: 'arc', cx, cy, r, a0, a1, length: Math.abs(a1 - a0) * r });

  for (let c = 0; c < columns; c++) {
    const goingUp = c % 2 === 0;
    const x = colX(c);
    // First column starts at the very bottom, last column ends at the very top.
    const yFrom = goingUp ? (c === 0 ? size - margin : bottom) : top;
    const yTo = goingUp ? (c === columns - 1 ? margin : top) : bottom;
    line({ x, y: yFrom }, { x, y: yTo });

    if (c < columns - 1) {
      const cx = x + r;
      // Screen space (y down): over the top goes PI -> 2PI, under the bottom goes PI -> 0.
      if (goingUp) arc(cx, top, Math.PI, Math.PI * 2);
      else arc(cx, bottom, Math.PI, 0);
    }
  }

  const total = segments.reduce((s, seg) => s + seg.length, 0);
  const count = FINISH_INDEX + 1;
  const step = total / (count - 1);

  const points: Point[] = [];
  for (let i = 0; i < count; i++) points.push(sample(segments, Math.min(i * step, total)));
  return points;
}

function sample(segments: Segment[], distance: number): Point {
  let d = distance;
  for (const seg of segments) {
    if (d <= seg.length || seg === segments[segments.length - 1]) {
      const t = seg.length === 0 ? 0 : Math.min(1, d / seg.length);
      if (seg.kind === 'line') {
        return { x: seg.a.x + (seg.b.x - seg.a.x) * t, y: seg.a.y + (seg.b.y - seg.a.y) * t };
      }
      const a = seg.a0 + (seg.a1 - seg.a0) * t;
      return { x: seg.cx + Math.cos(a) * seg.r, y: seg.cy + Math.sin(a) * seg.r };
    }
    d -= seg.length;
  }
  throw new Error('unreachable');
}
