import { CONFIG, FINISH_INDEX, START_INDEX } from '../config';
import {
  generateBoard,
  generateFatal,
  multiplierAt,
  pickJumpTarget,
  rollLoot,
  round2,
  type BoardSetup,
  type LinkKind,
  type LootItem,
} from '../board/rules';
import { FINISH_MULTIPLIER } from '../board/multipliers';
import { randInt } from '../rng';
import { NO_CHEATS, rollDice, type CheatFlags } from './dice';

export type RoundStatus = 'ready' | 'playing' | 'busted' | 'finished' | 'cashedOut';

/** What happened during one roll, in order. The view animates these; the simulator inspects them. */
export type StepEvent =
  | { type: 'move'; from: number; to: number }
  | { type: 'link'; kind: LinkKind; from: number; to: number }
  | { type: 'loot'; cell: number; item: LootItem; amount: number; jumpTo: number | null }
  | { type: 'jump'; from: number; to: number }
  | { type: 'bust'; cell: number }
  | { type: 'finish' };

export interface StepResult {
  /** [main, bonus]; bonus is 0 when the bonus dice was not active. */
  dice: [number, number];
  events: StepEvent[];
}

/**
 * Pure round logic, shared by the game view and the simulator. No rendering, no balance:
 * the caller takes the bet before the first roll and credits `lootWon` / payouts itself.
 */
export class Round {
  readonly setup: BoardSetup;
  status: RoundStatus = 'ready';
  position = START_INDEX;
  /** Fatal cells ahead of the player for the next roll. */
  fatal: Set<number>;
  /** The next roll throws an extra dice. */
  bonusDice = false;
  steps = 0;
  /** Loot money paid out during this round; it is kept even on bust. */
  lootWon = 0;

  constructor(readonly bet: number, setup: BoardSetup = generateBoard()) {
    // Own copy of the lootboxes: opening one mutates the set.
    this.setup = { links: setup.links, lootboxes: new Set(setup.lootboxes) };
    this.fatal = generateFatal(this.position, this.setup);
  }

  get alive(): boolean {
    return this.status === 'ready' || this.status === 'playing';
  }

  get canCashOut(): boolean {
    return this.status === 'playing' && this.position > START_INDEX && this.position < FINISH_INDEX;
  }

  /** Payout if the player cashed out now. */
  get cashOutValue(): number {
    return round2(this.bet * multiplierAt(this.position));
  }

  get finishValue(): number {
    return round2(this.bet * FINISH_MULTIPLIER);
  }

  roll(cheats: CheatFlags = NO_CHEATS): StepResult {
    if (!this.alive) throw new Error(`Cannot roll in status ${this.status}`);
    this.status = 'playing';
    this.steps++;

    const dice = rollDice(this.position, this.setup, this.fatal, this.bonusDice, cheats);
    // The bonus dice lasts for a single step.
    this.bonusDice = false;
    const events: StepEvent[] = [];

    const to = Math.min(this.position + dice[0] + dice[1], FINISH_INDEX);
    events.push({ type: 'move', from: this.position, to });
    this.position = to;
    if (to === FINISH_INDEX) return this.finish(dice, events);

    if (this.fatal.has(to)) {
      this.status = 'busted';
      this.fatal = new Set();
      events.push({ type: 'bust', cell: to });
      return { dice, events };
    }

    const link = this.setup.links.get(to);
    if (link) {
      events.push({ type: 'link', kind: link.kind, from: to, to: link.to });
      this.position = link.to;
    }

    if (this.setup.lootboxes.has(this.position)) {
      const cell = this.position;
      this.setup.lootboxes.delete(cell);
      let item = rollLoot();
      const jumpTo = item === 'jump' ? pickJumpTarget(cell, this.setup) : null;
      if (item === 'jump' && jumpTo === null) item = 'money';

      let amount = 0;
      if (item === 'money') {
        const { min, max } = CONFIG.loot.moneyBets;
        amount = round2(this.bet * randInt(min, max));
        this.lootWon = round2(this.lootWon + amount);
      } else if (item === 'bonusDice') {
        this.bonusDice = true;
      }
      events.push({ type: 'loot', cell, item, amount, jumpTo });

      if (item === 'jump' && jumpTo !== null) {
        events.push({ type: 'jump', from: cell, to: jumpTo });
        this.position = jumpTo;
        if (jumpTo === FINISH_INDEX) return this.finish(dice, events);
      }
    }

    this.fatal = generateFatal(this.position, this.setup);
    return { dice, events };
  }

  /** Ends the round and returns the payout. */
  cashOut(): number {
    if (!this.canCashOut) throw new Error('Cannot cash out now');
    this.status = 'cashedOut';
    this.bonusDice = false;
    this.fatal = new Set();
    return this.cashOutValue;
  }

  private finish(dice: [number, number], events: StepEvent[]): StepResult {
    this.status = 'finished';
    this.fatal = new Set();
    events.push({ type: 'finish' });
    return { dice, events };
  }
}
