import { Container, type Application } from 'pixi.js';
import { CONFIG, FINISH_INDEX, START_INDEX } from '../config';
import { buildBoardPoints } from '../board/layout';
import { multiplierAt, round2 } from '../board/rules';
import { FINISH_MULTIPLIER } from '../board/multipliers';
import { Round, type StepEvent } from '../engine/Round';
import type { CheatFlags } from '../engine/dice';
import { BoardView } from '../view/BoardView';
import { Token } from '../view/Token';
import { Camera, type Rect } from '../view/Camera';
import { Hud } from '../view/Hud';
import { Banner } from '../view/Banner';
import { ArrowPad } from '../view/ArrowPad';
import { CameraControls } from './CameraControls';
import { tween, wait, linear } from '../util/tween';

const TOKEN_COLOR = 0xffd166;
const DEAD_COLOR = 0xe03a3a;

export class Game {
  private readonly world = new Container();
  private readonly board: BoardView;
  private readonly token = new Token();
  private readonly camera: Camera;
  private readonly hud = new Hud();
  private readonly banner = new Banner();
  private readonly arrowPad = new ArrowPad();
  private readonly cameraControls: CameraControls;

  private balance: number = CONFIG.economy.startBalance;
  private readonly bet: number = CONFIG.economy.bet;
  private round!: Round;
  /** An animation or round transition is in progress; input is ignored. */
  private busy = false;

  constructor(private readonly app: Application) {
    this.board = new BoardView(buildBoardPoints());
    this.world.addChild(this.board, this.token);
    this.camera = new Camera(this.world, this.token);
    this.cameraControls = new CameraControls(app.canvas, this.camera, this.arrowPad);
    app.stage.addChild(this.world, this.arrowPad, this.hud, this.banner);

    this.hud.rollButton.on('pointertap', (e) => this.roll({ avoidFatal: e.ctrlKey, toLootbox: e.shiftKey }));
    this.hud.cashButton.on('pointertap', () => this.cashOut());
    window.addEventListener('keydown', (e) => {
      if (e.code === 'Space' || e.code === 'Enter') this.roll({ avoidFatal: e.ctrlKey, toLootbox: e.shiftKey });
      if (e.code === 'KeyC') this.cashOut();
    });

    app.ticker.add((tk) => {
      this.board.update(tk.deltaMS);
      this.cameraControls.update(tk.deltaMS / 1000);
      this.camera.update(tk.deltaMS / 1000);
    });

    const onResize = () => {
      app.resize();
      this.layout();
    };
    window.addEventListener('resize', onResize);
    window.addEventListener('orientationchange', () => setTimeout(onResize, 100));

    this.startRound();
    this.layout();
    this.camera.snap();
  }

  private layout(): void {
    const { width: w, height: h } = this.app.screen;
    const portrait = h > w;
    let panel: Rect;
    let play: Rect;
    if (portrait) {
      const ph = clamp(h * 0.3, 170, 280);
      panel = { x: 0, y: h - ph, w, h: ph };
      play = { x: 0, y: 0, w, h: h - ph };
    } else {
      const pw = clamp(w * 0.28, 190, 340);
      panel = { x: w - pw, y: 0, w: pw, h };
      play = { x: 0, y: 0, w: w - pw, h };
    }
    this.hud.layout(panel, portrait);
    this.camera.setViewport(play);
    this.banner.position.set(play.x + play.w / 2, play.y + play.h * 0.22);
    this.banner.scale.set(Math.min(1, play.w / 560));

    const button = clamp(Math.min(play.w, play.h) * 0.09, 40, 60);
    const margin = 12;
    this.arrowPad.draw(button);
    this.arrowPad.position.set(play.x + play.w - button * 3 - margin, play.y + play.h - button * 3 - margin);
  }

  private startRound(): void {
    this.round = new Round(this.bet);
    this.board.setLinks(this.round.setup.links);
    this.board.setLootboxes(this.round.setup.lootboxes);
    this.hud.setBonusDice(false);
    this.placeToken(START_INDEX);
    this.token.setColor(TOKEN_COLOR);
    this.token.scale.set(1);
    this.token.alpha = 1;
    this.board.setFatal(this.round.fatal);
    this.banner.hide();
    this.camera.follow();
    this.updateHud();
  }

  private async roll(cheats: CheatFlags): Promise<void> {
    if (this.busy) return;

    if (this.round.status === 'ready') {
      if (this.balance < this.bet) {
        // Prototype convenience: refill instead of a game-over screen.
        this.balance = CONFIG.economy.startBalance;
        this.updateHud();
        return;
      }
      this.balance = round2(this.balance - this.bet);
    }

    this.busy = true;
    this.camera.follow();
    const { dice, events } = this.round.roll(cheats);
    this.updateHud();

    await Promise.all([
      this.hud.dice.roll(this.app.ticker, dice[0], CONFIG.anim.diceRollMs),
      dice[1] ? this.hud.bonusDice.roll(this.app.ticker, dice[1], CONFIG.anim.diceRollMs) : Promise.resolve(),
    ]);

    for (const event of events) {
      switch (event.type) {
        case 'move':
          for (let i = event.from + 1; i <= event.to; i++) await this.hopTo(i);
          this.hud.setBonusDice(false);
          break;
        case 'link':
          await this.slideTo(event.to);
          break;
        case 'loot':
          await this.showLoot(event);
          break;
        case 'jump':
          this.board.setFatal(new Set());
          await this.jumpTo(event.to);
          break;
        case 'bust':
          await this.bust();
          return;
        case 'finish':
          await this.endRound(this.round.finishValue, FINISH_MULTIPLIER, 'FINISH!', 0xffd166);
          return;
      }
    }

    this.board.setFatal(this.round.fatal);
    this.busy = false;
    this.updateHud();
  }

  private async cashOut(): Promise<void> {
    if (this.busy || !this.round.canCashOut) return;
    this.busy = true;
    const multiplier = multiplierAt(this.round.position);
    const win = this.round.cashOut();
    this.hud.setBonusDice(false);
    await this.endRound(win, multiplier, 'CASHED OUT', 0x46c46a);
  }

  private async showLoot(event: Extract<StepEvent, { type: 'loot' }>): Promise<void> {
    const box = this.board.lootbox(event.cell);
    if (box) {
      await tween(this.app.ticker, 300, (t) => {
        box.scale.set(1 + t * 0.8);
        box.alpha = 1 - t;
      });
      box.destroy();
    }

    if (event.item === 'money') {
      this.balance = round2(this.balance + event.amount);
      this.updateHud();
      this.banner.show('BONUS MONEY', `+${event.amount.toFixed(2)}`, 0x46c46a);
    } else if (event.item === 'bonusDice') {
      this.hud.setBonusDice(true);
      this.banner.show('BONUS DICE', 'Next roll uses two dice', 0xffd166);
    } else {
      const text = event.jumpTo === FINISH_INDEX ? 'Straight to Finish' : `Forward ${event.jumpTo! - event.cell} cells`;
      this.banner.show('JUMP!', text, 0x5ab4ff);
    }
    await wait(this.app.ticker, CONFIG.anim.lootRevealMs);
    this.banner.hide();
  }

  private async endRound(win: number, multiplier: number, title: string, color: number): Promise<void> {
    this.balance = round2(this.balance + win);
    this.board.setFatal(new Set());
    this.updateHud();
    this.banner.show(title, `x${multiplier.toFixed(2)}  ·  +${win.toFixed(2)}`, color);
    await wait(this.app.ticker, CONFIG.anim.roundEndDelayMs);
    this.busy = false;
    this.startRound();
  }

  private async bust(): Promise<void> {
    this.token.setColor(DEAD_COLOR);
    this.board.setFatal(new Set());
    this.banner.show('BUSTED', `-${this.bet.toFixed(2)}`, DEAD_COLOR);
    this.updateHud();
    await tween(this.app.ticker, 500, (t) => this.token.scale.set(1 + Math.sin(t * Math.PI * 3) * 0.25));
    await tween(this.app.ticker, 400, (t) => (this.token.alpha = 1 - t * 0.6));
    await wait(this.app.ticker, CONFIG.anim.roundEndDelayMs - 900);
    this.busy = false;
    this.startRound();
  }

  private placeToken(index: number): void {
    const p = this.board.cellPosition(index);
    this.token.position.set(p.x, p.y);
  }

  private hopTo(index: number): Promise<void> {
    const from = { x: this.token.x, y: this.token.y };
    const to = this.board.cellPosition(index);
    return tween(
      this.app.ticker,
      CONFIG.anim.hopMs,
      (t) => {
        const lift = Math.sin(t * Math.PI) * 45;
        this.token.position.set(from.x + (to.x - from.x) * t, from.y + (to.y - from.y) * t - lift);
        this.token.scale.set(1 + Math.sin(t * Math.PI) * 0.15);
      },
      linear,
    );
  }

  private jumpTo(index: number): Promise<void> {
    const from = { x: this.token.x, y: this.token.y };
    const to = this.board.cellPosition(index);
    return tween(this.app.ticker, CONFIG.anim.jumpMs, (t) => {
      const lift = Math.sin(t * Math.PI) * 220;
      this.token.position.set(from.x + (to.x - from.x) * t, from.y + (to.y - from.y) * t - lift);
      this.token.scale.set(1 + Math.sin(t * Math.PI) * 0.4);
    });
  }

  private slideTo(index: number): Promise<void> {
    const from = { x: this.token.x, y: this.token.y };
    const to = this.board.cellPosition(index);
    return tween(this.app.ticker, CONFIG.anim.slideMs, (t) => {
      this.token.position.set(from.x + (to.x - from.x) * t, from.y + (to.y - from.y) * t);
    });
  }

  private updateHud(): void {
    const { position, status } = this.round;
    const onCell = status === 'playing' && position > START_INDEX && position < FINISH_INDEX;
    const mult = onCell ? multiplierAt(position) : 0;
    this.hud.setStats(
      {
        balance: this.balance.toFixed(2),
        bet: this.bet.toFixed(2),
        multiplier: onCell ? `x${mult.toFixed(2)}` : '—',
        win: onCell ? this.round.cashOutValue.toFixed(2) : '—',
      },
      0x46c46a,
    );

    const ready = status === 'ready';
    const needsRefill = ready && this.balance < this.bet;
    this.hud.rollButton.setText(needsRefill ? 'REFILL' : ready ? `BET ${this.bet} & ROLL` : 'ROLL');
    this.hud.rollButton.setEnabled(!this.busy);
    this.hud.cashButton.setEnabled(!this.busy && this.round.canCashOut);
    this.cameraControls.setEnabled(!this.busy);
  }
}

function clamp(v: number, min: number, max: number): number {
  return Math.max(min, Math.min(max, v));
}
