import { FINISH_INDEX } from '../config';
import type { BoardSetup } from '../board/rules';
import { randInt } from '../rng';

export interface CheatFlags {
  /** Ctrl: never land on a fatal cell. */
  avoidFatal: boolean;
  /** Shift: land on a lootbox if one is within reach. */
  toLootbox: boolean;
}

export const NO_CHEATS: CheatFlags = { avoidFatal: false, toLootbox: false };

/**
 * Rolls the main dice (and the bonus dice when `withBonus`), bending the result
 * when cheats are on. Returns [main, bonus]; bonus is 0 without the bonus dice.
 * A cheat that cannot be satisfied falls back to a fair roll.
 */
export function rollDice(
  pos: number,
  setup: BoardSetup,
  fatal: Set<number>,
  withBonus: boolean,
  cheats: CheatFlags,
): [number, number] {
  const minTotal = withBonus ? 2 : 1;
  const maxTotal = withBonus ? 12 : 6;
  const landing = (total: number) => Math.min(pos + total, FINISH_INDEX);

  let totals: number[] = [];
  if (cheats.toLootbox) {
    for (let t = minTotal; t <= maxTotal; t++) if (setup.lootboxes.has(landing(t))) totals.push(t);
  }
  if (totals.length === 0 && cheats.avoidFatal) {
    for (let t = minTotal; t <= maxTotal; t++) if (!fatal.has(landing(t))) totals.push(t);
  }
  if (totals.length === 0) {
    const main = randInt(1, 6);
    return [main, withBonus ? randInt(1, 6) : 0];
  }

  const total = totals[randInt(0, totals.length - 1)];
  if (!withBonus) return [total, 0];
  const main = randInt(Math.max(1, total - 6), Math.min(6, total - 1));
  return [main, total - main];
}
